import { getTransactionEarnings } from '~/client';

export const useEarningsTransactionsBreakdown = defineQuery(() => {
  const route = useRoute();
  const transactionId = computed(() => {
    return route.name === 'earnings-transactions-id' ? route.params.id.toString() : '';
  });

  const {
    data: transactionEarningsBreakdownData,
    error,
    isLoading,
    refetch,
  } = useQuery({
    key: () => ['transactions-details-breakdown', transactionId.value],
    query: () => getTransactionEarnings({ composable: '$fetch', path: { transaction_id: transactionId.value } }),
    staleTime: 0,
    enabled: () => !!transactionId.value && useRoute().name === 'earnings-transactions-id',
  });

  return {
    transactionEarningsBreakdownData,
    transactionEarnings: computed(() => transactionEarningsBreakdownData.value?.items || []),
    error,
    isLoading,
    transactionId,
    refetch,
  };
});
