import { getTransactionDetails } from '~/client';

export const useEarningsTransactionsDetails = defineQuery(() => {
  const route = useRoute();
  const transactionId = computed(() => (route.name === 'earnings-transactions-id' ? route.params.id.toString() : ''));

  const {
    data: transactionDetails,
    error,
    isLoading,
  } = useQuery({
    key: () => ['transactions-details', transactionId.value],
    query: () => getTransactionDetails({ composable: '$fetch', path: { transaction_id: transactionId.value } }),
    staleTime: 0,
    enabled: () => !!transactionId.value && useRoute().name === 'earnings-transactions-id',
  });

  return {
    transactionDetails,
    error,
    isLoading,
    transactionId,
  };
});
