import type {
  TransactionDetailsForAdmin,
  TransactionDetailsForManager,
  TransactionDetailsForCanvasser,
} from '~/client';

export const isTransactionDetailsForAdminManager = (
  details: TransactionDetailsForAdmin | TransactionDetailsForManager | TransactionDetailsForCanvasser
): details is TransactionDetailsForAdmin | TransactionDetailsForManager => {
  return 'canvasser' in details;
};

export const isTransactionDetailsForCanvasser = (
  details: TransactionDetailsForAdmin | TransactionDetailsForManager | TransactionDetailsForCanvasser
): details is TransactionDetailsForCanvasser => {
  return !isTransactionDetailsForAdminManager(details);
};
