<template>
  <section class="grid grid-cols-2 gap-6">
    <PageTitle title="Transaction details" class="col-span-2" show-doc />
    <div class="col-span-2 flex flex-wrap justify-between items-center gap-4">
      <GoBackButton subject="transactions" :fallback-to="{ name: 'earnings-transactions' }" />
      <Badge
        v-if="transactionDetails?.status"
        :variant="getTransactionStatusBadge(transactionDetails.status).variant"
        >{{ getTransactionStatusBadge(transactionDetails.status).label }}</Badge
      >
    </div>
    <AppLoader v-if="isLoading" subject="transaction details" class="col-span-2" />
    <AppError v-else-if="error" :error="error" title="Failed to load transaction details" class="col-span-2" />
    <AppEmpty v-else-if="!transactionDetails" class="col-span-2" subject="transaction details" />
    <Card v-else class="grid col-span-2">
      <CardContent class="flex flex-col gap-4">
        <div class="flex flex-wrap justify-between items-center">
          <LabeledValue label="Amount">
            <span class="text-3xl font-semibold">{{ formatAmount(transactionDetails.amount / 100) }}</span>
          </LabeledValue>
          <LabeledEntityDate label="Issue date" :date="transactionDetails.created_at" />
        </div>
        <template v-if="isTransactionDetailsForAdminManager(transactionDetails)">
          <Separator />
          <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
            <LabeledValue label="Type">
              <Badge class="capitalize">{{ transactionDetails.type.replaceAll('_', ' ').toLowerCase() }}</Badge>
            </LabeledValue>
            <LabeledEntityUser :user-id="transactionDetails.canvasser.id" />
          </div>
        </template>
        <template
          v-if="
            isTransactionDetailsForAdminManager(transactionDetails) &&
            (transactionDetails.status === 'FAILED' || !transactionDetails.status)
          "
        >
          <Separator />
          <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
            <LabeledValue label="Reason Code">
              <p class="capitalize">
                {{ transactionDetails.reason_code?.replaceAll('_', ' ').toLowerCase() || 'N/A' }}
              </p>
            </LabeledValue>
            <LabeledValue label="Label">
              <p>{{ transactionDetails.error_label || 'N/A' }}</p>
            </LabeledValue>
            <LabeledValue class="col-span-full" label="Message" value-class="line-clamp-none">
              <p>
                {{ transactionDetails.error_message || 'N/A' }}
              </p>
            </LabeledValue>
          </div>
        </template>
        <Separator />
        <h3 class="text-xl font-semibold">Breakdown</h3>
        <AppLoader v-if="isLoadingBreakdown" variant="inline" subject="breakdown" />
        <AppError
          v-else-if="breakdownError"
          title="Failed to load breakdown"
          :error="breakdownError"
          variant="table"
          :action="refetchBreakdown"
          action-text="Retry"
        />
        <AppEmpty v-else-if="!transactionEarningsBreakdownData" subject="breakdown" variant="table" />
        <EarningsListCanvasserTable v-else-if="isCanvasser" :list="processedCanvasserBreakdownList" />
        <EarningsListAdminManagerTable
          v-else-if="isAdminOrManager"
          :list="processedAdminManagerBreakdownList"
          remove-canvasser-column
        />
      </CardContent>
    </Card>
  </section>
</template>

<script setup lang="ts">
import type { EarningListItemForCanvasser, EarningListItemForAdmin, EarningListItemForManager } from '~/client';
import { useEarningsTransactionsDetails } from '~/queries/earnings/transactions/details';
import { getTransactionStatusBadge } from '~/constants/earnings/transactionStatus';
import { useEarningsTransactionsBreakdown } from '~/queries/earnings/transactions/breakdown';

useHead({
  title: 'Transaction details',
});

definePageMeta({
  roles: ['admin', 'manager', 'canvasser'],
  backLabel: 'transaction',
});

const { timezone, isCanvasser, isAdminOrManager } = useUserRole();

const { transactionDetails, error, isLoading } = useEarningsTransactionsDetails();
const {
  transactionEarningsBreakdownData,
  transactionEarnings,
  error: breakdownError,
  isLoading: isLoadingBreakdown,
  refetch: refetchBreakdown,
} = useEarningsTransactionsBreakdown();

const processedCanvasserBreakdownList = computed((): EarningListItemForCanvasser[] => {
  if (isEarningListForCanvasser(transactionEarnings.value)) {
    return transactionEarnings.value;
  } else return [];
});

const processedAdminManagerBreakdownList = computed((): (EarningListItemForAdmin | EarningListItemForManager)[] => {
  if (isEarningListForAdminManager(transactionEarnings.value)) {
    return transactionEarnings.value;
  } else return [];
});
</script>
